 "content": "def transform(grid):
    """Partition the 8-pattern into 2x2 squares and L triominoes, color by piece."""
    h, w = len(grid), len(grid[0])
    occupied = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != 0}
    pieces = []
    for r in range(h - 1):
        for c in range(w - 1):
            box = {(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)}
            if box <= occupied:
                pieces.append((box, 1))
            for miss, color in [((r, c), 2), ((r + 1, c), 3), ((r, c + 1), 4), ((r + 1, c + 1), 5)]:
                tri = box - {miss}
                if tri <= occupied:
                    pieces.append((tri, color))
    by_cell = {p: [] for p in occupied}
    for cells, color in pieces:
        for p in cells:
            by_cell[p].append((cells, color))

    def cover(left):
        if not left:
            return []
        p = min(left, key=lambda q: sum(cells <= left for cells, _ in by_cell[q]))
        for cells, color in by_cell[p]:
            if cells <= left:
                rest = cover(left - cells)
                if rest is not None:
                    return [(cells, color)] + rest
        return None

    solution = cover(occupied)
    if solution is None:
        raise ValueError('No exact tiling into demonstrated pieces')
    out = [[0] * w for _ in range(h)]
    for cells, color in solution:
        for r, c in cells:
            out[r][c] = color
    return out
